export const RATE_SOURCE='https://www.bok.or.kr/portal/singl/baseRate/list.do?dataSeCd=01&menuNo=400214';
export const CPI_SOURCE='https://www.index.go.kr/unity/potal/indicator/timeSeriesStblGams.do?freq=Y&idx_cd=4226&period=1965:2024&stts_cd=422601';
export const POLICY_RATE_CHANGES=[['2002-05-07',4.25],['2003-05-13',4],['2003-07-10',3.75],['2004-08-12',3.5],['2004-11-11',3.25],['2005-10-11',3.5],['2005-12-08',3.75],['2006-02-09',4],['2006-06-08',4.25],['2006-08-10',4.5],['2007-07-12',4.75],['2007-08-09',5],['2008-08-07',5.25],['2008-10-09',5],['2008-10-27',4.25],['2008-11-07',4],['2008-12-11',3],['2009-01-09',2.5],['2009-02-12',2],['2010-07-09',2.25],['2010-11-16',2.5],['2011-01-13',2.75],['2011-03-10',3],['2011-06-10',3.25],["2012-07-12",3],["2012-10-11",2.75],["2013-05-09",2.5],["2014-08-14",2.25],["2014-10-15",2],["2015-03-12",1.75],["2015-06-11",1.5],["2016-06-09",1.25],["2017-11-30",1.5],["2018-11-30",1.75],["2019-07-18",1.5],["2019-10-16",1.25],["2020-03-17",0.75],["2020-05-28",0.5],["2021-08-26",0.75],["2021-11-25",1],["2022-01-14",1.25],["2022-04-14",1.5],["2022-05-26",1.75],["2022-07-13",2.25],["2022-08-25",2.5],["2022-10-12",3],["2022-11-24",3.25],["2023-01-13",3.5],["2024-10-11",3.25],["2024-11-28",3],["2025-02-25",2.75],["2025-05-29",2.5],["2026-07-16",2.75],["2026-08-27",3]].map(([date,percent])=>({date,percent,source:RATE_SOURCE}));
export const ANNUAL_CPI=Object.fromEntries([2.8,3.5,3.6,2.8,2.2,2.5,4.7,2.8,2.9,4,2.2,1.3,1.3,.7,1,1.9,1.5,.4,.5,2.5,5.1,3.6,2.3].map((percent,i)=>[2002+i,percent]));
export function policyRateAt(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date<'2002-12-01'||date>'2026-10-12')return null;const row=POLICY_RATE_CHANGES.findLast(x=>x.date<=date);return row?{...row,label:date<'2008-03-01'?'콜금리 목표':'한국은행 기준금리',asOf:date}:null;}
export function macroReference(s){const asOf=s.month===s.start?s.startDate||s.month+'-01':s.month+'-01',year=Number(s.month.slice(0,4))-1,startYear=Number(s.start.slice(0,4))-1;let ratio=1;if(startYear<2002||year>2024||year<startYear)ratio=null;else for(let y=startYear+1;y<=year;y++){if(ANNUAL_CPI[y]===undefined){ratio=null;break;}ratio*=1+ANNUAL_CPI[y]/100;}return {rate:policyRateAt(asOf),cpiYear:year,cpiPercent:ANNUAL_CPI[year]??null,annualPriceRatio:ratio,startReferenceYear:startYear};}
export function renderObservedMacro(s,{won,escape:e},netWorth){const r=macroReference(s);return `<details class="finance-help"><summary>공식 금리·물가 · 게임 모형과 비교</summary><div class="household-budget"><div><span>${r.rate?.label||'한국 정책금리'}</span><b>${r.rate?r.rate.percent.toFixed(2)+'%':'연결 범위 밖'}</b></div><div><span>전년도 연평균 소비자물가 변화 · ${r.cpiYear}년</span><b>${r.cpiPercent===null?'자료 미연결':r.cpiPercent.toFixed(1)+'%'}</b></div>${r.annualPriceRatio!==null?`<div><span>공식 연평균 물가 참고 구매력 · ${r.startReferenceYear}년 기준</span><b>${won(Math.round(netWorth/r.annualPriceRatio))}</b></div>`:''}</div><p>금리는 ${r.rate?e(r.rate.asOf):'2002-12-01~2026-10-12 범위'} 기준입니다. 2008년 2월까지는 콜금리 목표입니다. 실제 은행상품 금리와 같지 않으며 게임 예금·대출에 그대로 대입하지 않습니다.</p><p>물가는 전년도까지의 연평균 변화입니다. 현재 연도의 연간 결과를 미리 공개하지 않습니다. 월별 물가지수·월별 비용 재현이 아니며 게임 생활비와 물가 배율은 여전히 별도 모형입니다. 연평균 기준 구매력은 보조 비교값입니다.</p><a href="${RATE_SOURCE}" target="_blank" rel="noopener noreferrer">한국은행 정책금리 기록 ↗</a> · <a href="${CPI_SOURCE}" target="_blank" rel="noopener noreferrer">국가지표체계 소비자물가 ↗</a></details>`;}
